// Software projection of a three-dimensional mesh. No measured flame field is implied.
export class Scene{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.yaw=.4;this.pitch=.25;this.radius=1;this.initial=1;let drag=null;canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){this.yaw+=(e.clientX-drag[0])*.01;this.pitch=Math.max(-1.3,Math.min(1.3,this.pitch+(e.clientY-drag[1])*.01));drag=[e.clientX,e.clientY];this.draw()}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();this.yaw+=(e.key==='ArrowRight'?.12:e.key==='ArrowLeft'?-.12:0);this.pitch=Math.max(-1.3,Math.min(1.3,this.pitch+(e.key==='ArrowDown'?.12:e.key==='ArrowUp'?-.12:0)));this.draw()}});new ResizeObserver(()=>this.draw()).observe(canvas);}
 set(d,d0){this.radius=Math.max(0,d/2);this.initial=d0/2;this.draw()}
 draw(){const c=this.ctx;if(!c)return;const box=this.canvas.getBoundingClientRect(),w=box.width,h=box.height,dpr=devicePixelRatio||1;this.canvas.width=w*dpr;this.canvas.height=h*dpr;c.scale(dpr,dpr);c.clearRect(0,0,w,h);const scale=Math.min(w,h)*.105/Math.max(this.initial,.2);const project=([x,y,z])=>{let a=x*Math.cos(this.yaw)+z*Math.sin(this.yaw),b=-x*Math.sin(this.yaw)+z*Math.cos(this.yaw),v=y*Math.cos(this.pitch)-b*Math.sin(this.pitch),depth=y*Math.sin(this.pitch)+b*Math.cos(this.pitch);let perspective=7/(7-depth/Math.max(this.initial,.2));return[w/2+a*scale*perspective,h/2-v*scale*perspective,depth]};const line=(points,color,width=1)=>{c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach((p,i)=>{let [x,y]=project(p);i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()};let r=this.initial;
 for(let i=-4;i<=4;i++){line([[i*r,-2.2*r,-4*r],[i*r,-2.2*r,4*r]],'#243d4e');line([[-4*r,-2.2*r,i*r],[4*r,-2.2*r,i*r]],'#243d4e')}
 if(this.radius>0){let f=this.radius*2.5;let glow=c.createRadialGradient(w/2,h/2,this.radius*scale,w/2,h/2,f*scale*1.25);glow.addColorStop(0,'rgba(255,164,91,0)');glow.addColorStop(.45,'rgba(255,142,71,.06)');glow.addColorStop(.7,'rgba(255,172,96,.25)');glow.addColorStop(.83,'rgba(255,177,99,.08)');glow.addColorStop(1,'rgba(255,156,84,0)');c.fillStyle=glow;c.fillRect(0,0,w,h);for(let j=0;j<12;j++){let theta=j*Math.PI/12;line(Array.from({length:97},(_,i)=>{let p=i/96*Math.PI*2;return[f*Math.cos(p)*Math.cos(theta),f*Math.sin(p),f*Math.cos(p)*Math.sin(theta)]}),'rgba(255,169,102,.28)')}for(let j=-3;j<=3;j++){let phi=j*Math.PI/8;line(Array.from({length:97},(_,i)=>{let p=i/96*Math.PI*2;return[f*Math.cos(phi)*Math.cos(p),f*Math.sin(phi),f*Math.cos(phi)*Math.sin(p)]}),'rgba(255,191,134,.32)')}
 let faces=[],n=28,m=16,sphere=(i,j)=>{let a=i/n*Math.PI*2,b=(j/m-.5)*Math.PI;return[this.radius*Math.cos(b)*Math.cos(a),this.radius*Math.sin(b),this.radius*Math.cos(b)*Math.sin(a)]};for(let j=0;j<m;j++)for(let i=0;i<n;i++){let p=[sphere(i,j),sphere(i+1,j),sphere(i+1,j+1),sphere(i,j+1)].map(project);faces.push({p,z:p.reduce((s,p)=>s+p[2],0)/4,light:35+35*(j/m)+10*Math.sin(i/n*Math.PI*2)});}faces.sort((a,b)=>a.z-b.z);for(let f of faces){c.fillStyle=`hsl(184 35% ${f.light}%)`;c.beginPath();f.p.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.fill();} }
 line([[0,-2.2*r,0],[r,-2.2*r,0]],'#77e4de',3);const p=project([r,-2.2*r,0]);c.fillStyle='#b6d7df';c.font='11px system-ui';c.fillText(`${r.toFixed(2)} mm · grid spacing`,Math.max(5,p[0]-30),p[1]+20);c.fillStyle='#a4b5c8';c.fillText('X / Y / Z orbit · schematic shell',12,20);
 }
}
